"""Real UDP host/net and loading helpers; fake clock/UI, not full app."""
import importlib.util, tempfile, subprocess
from pathlib import Path
r=Path(__file__).resolve().parents[1]
sp=importlib.util.spec_from_file_location('fx',r/'tests/test_vs_local_host_recovery_udp.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)
base=m.client_source()
assert base.count('G.vs_seen_loaded=3;vs_recovery_begin(&G.vs_go);VR.local_loaded=1;') == 1
assert base.count('static void vs_off(void){net_close();}') == 1
assert base.count('void fixture_poll(double now,int status){clock_seconds=now;net_poll(now,status,"new",profile,sizeof profile);}') == 1
s='#include <assert.h>\n#include <stdio.h>\n'+base.replace('G.vs_seen_loaded=3;vs_recovery_begin(&G.vs_go);VR.local_loaded=1;','G.vs_seen_loaded=0;vs_recovery_begin(&G.vs_go);VR.local_loaded=0;').replace('static void vs_off(void){net_close();}','#define MENU_VS_LOADED 70\nstatic void vs_off(void){net_close();}').replace('void fixture_poll(double now,int status){clock_seconds=now;net_poll(now,status,"new",profile,sizeof profile);}','extern int legacy; void fixture_poll(double now,int status){unsigned char base[21]={0};vs_recovery_wire_extension e={0,VR.race,VR.nonce,++VR.seq};clock_seconds=now;assert(vs_recovery_wire_encode(profile,sizeof profile,base,sizeof base,&e));assert(vs_recovery_wire_put_ready(profile,sizeof profile,VR.local_loaded));net_poll(now,status,"new",profile,legacy?21:47);}')
s+='\n'+m.support.block((r/'src/app.c').read_text(),'static int vs_others_loaded(')+'''\nvoid loaded_set(int i){load(i);VR.local_loaded=1;save(i);} int loaded_check(int i,int *match){load(i);*match=vs_host_loading_lobby_matches(net_lobby_valid_now(),G.vs_go.race);int ret=vs_others_loaded();save(i);return ret;} int begin_debug(int i){load(i);int pending=net_go_pending();if(!pending){save(i);return 0;} int take=net_take_go(&G.vs_go);G.vs_seen_loaded=0;G.vs_race=1;vs_recovery_begin(&G.vs_go);printf("BEGIN i=%d pending=%d take=%d race=%u n=%d pcb=%d ids=%u,%u initialized=%d VHunknown=%d VHtime=%g VHhas=%d clock=%g\\n",i,pending,take,G.vs_go.race,G.vs_go.n,G.vs_go.pcb,G.vs_go.player[0].id,G.vs_go.player[1].id,VR.recovery.initialized,VH.unknown,VH_last_time,VH_has_time,clock_seconds);int ok=take&&VR.recovery.initialized;save(i);return ok?1:-1;}\n'''
main='''#include <assert.h>\n#include <stdio.h>\n#include <unistd.h>\n#include "vs_host.h"\nint legacy;int host_port(void),host_count(void),begin_debug(int),client_observe(int),loaded_check(int,int*);void client_open(int,int),client_poll(int,double,int),client_close(int),loaded_set(int);\nint main(int argc,char**argv){(void)argv;legacy=argc>1;setbuf(stdout,0);assert(!vs_host_open(0,101));assert(vs_host_enable_local());for(int i=0;i<2;i++){client_open(i,host_port());client_poll(i,1,66);}for(int j=0;j<100&&host_count()<2;j++){usleep(1000);vs_host_poll(1,"host");}assert(host_count()==2);for(int i=0;i<2;i++)client_poll(i,1.1,66);assert(vs_host_arm_round()&&vs_host_seal_vote()&&vs_host_local_start(3,17,5,1.1));int started[2]={0,0};for(int j=0;j<500&&(!started[0]||!started[1]);j++){usleep(1000);for(int i=0;i<2;i++)if(!started[i]){client_poll(i,1.2,1);int z=begin_debug(i);if(z<0){printf("recovery failure\\n");return 4;}started[i]=z;}}if(!started[0]||!started[1]){printf("GO pending timeout owner=%d guest=%d\\n",started[0],started[1]);return 5;}vs_host_round_accepted();int done[2]={0,0},first[2]={-1,-1};for(int f=0;f<300;f++){double t=1.3+f/60.;if(f==40){loaded_set(0);loaded_set(1);}int st=f<40?1:70;vs_host_poll(t,"host");client_poll(0,t,st);if(client_observe(0)){printf("owner observer abort at %d\\n",f);return 6;}int match;int result=loaded_check(0,&match);if(!done[0]&&result&&match)done[0]=1,first[0]=f;client_poll(1,t,st);if(client_observe(1)){printf("guest observer abort at %d\\n",f);return 7;}result=loaded_check(1,&match);if(!done[1]&&result)done[1]=1,first[1]=f;if(done[0]&&done[1])break;}printf("%s owner=%d frame=%d guest=%d frame=%d\\n",legacy?"legacy21":"RFR47",done[0],first[0],done[1],first[1]);for(int i=0;i<2;i++)client_close(i);vs_host_close();return !(done[0]&&done[1]);}'''
with tempfile.TemporaryDirectory(prefix='vs-udp-') as x:
 d=Path(x)
 for n,t in [('host.c',m.HOST),('client.c',s),('main.c',main)]: (d/n).write_text(t)
 subprocess.run(['cc','-std=gnu11','-Wall','-Wextra','-Werror','-Wno-unused-function','-Wno-unused-variable','-fsanitize=undefined,float-cast-overflow','-fno-sanitize-recover=all','-D__ANDROID__','-I'+str(r/'src'),str(d/'host.c'),str(d/'client.c'),str(d/'main.c'),str(r/'src/vs_recovery.c'),str(r/'src/vs_recovery_wire.c'),str(r/'src/vs_abort_history.c'),'-o',str(d/'test')],check=True,timeout=30)
 for args in [['legacy'],[]]:
  p=subprocess.run([str(d/'test'),*args],timeout=15); print('exit',p.returncode,flush=True); p.check_returncode()
